\title{The $q$-ary Exact Coset-Guesswork Exponent\\ at the Maximal-Entropy Source}
\author{Aristotle}
\date{2026-07-14}

\begin{document}
\maketitle

\begin{abstract}
Guesswork quantifies the effort an optimal adversary expends to identify a secret
by sequential guessing, and its exponential growth rate---the \emph{guessing
exponent}---is a fundamental measure of information-theoretic security. We study how
a rate-$R$ coset code alters this exponent for a maximal-entropy (uniform) source
over an alphabet of $q \ge 2$ symbols. Constructing the $\rho$-th guesswork moment
from first principles as the exact average
$M_q(k) = q^{-k}\sum_{j=1}^{q^k} j^{\rho}$ over $q^k$ equiprobable candidates, we
prove an elementary two-sided estimate for the power sum $\sum_{k=1}^{q^j} k^{\rho}$
in base $q$ and use it, via a squeeze argument, to determine the exact per-symbol
growth rate. The unconstrained exponent is $\rho$; a rate-$R$ coset code yields
exactly $\rho R$; hence the code lowers the exponent by precisely the redundancy
term $\rho(1-R)$, uniformly in the alphabet size $q$. A companion Rényi-entropy
computation identifies the leading $\rho$ as $\rho$ times the (order-independent)
Rényi entropy of the uniform law, showing the exponent is the maximal-entropy
Arıkan--Merhav exponent. The result exhibits the redundancy shift as a pure density
phenomenon carried entirely by the factor $q^{-k}$, independent of both $\rho$'s fine
structure and the alphabet size.
\end{abstract}

\noindent\textbf{Keywords.} Guesswork, guessing exponent, coset codes, Rényi
entropy, Arıkan--Merhav exponent, power sums, maximal entropy, $q$-ary alphabets.

\section{Introduction}

\subsection{Guesswork and its moments}
Consider an adversary who must identify an unknown value $X$ taking values in a
finite set $\mathcal{X}$, knowing only the distribution of $X$. The adversary asks
questions of the form ``is $X = x$?'' one at a time, and the \emph{guesswork} $G(x)$
is the number of questions asked before the correct answer, when the true value is
$x$. An optimal adversary queries values in nonincreasing order of probability, so
that $G$ takes the value $j$ exactly when $x$ is the $j$-th most likely outcome.

Rather than the mean $\Exp[G]$, the quantities of information-theoretic interest are
the \emph{moments} $\Exp[G^{\rho}]$ for $\rho > 0$, and specifically their
exponential growth rate as the block length grows. This growth rate---the
\emph{guessing exponent}---governs the large-deviations behavior of sequential search
and the security margin of a secret against brute force.

\subsection{Maximal-entropy sources and coset codes}
We focus on a maximal-entropy (uniform) source over an alphabet of $q$ symbols. A
block of $m$ symbols has $q^m$ equiprobable candidate values, and an optimal
adversary realizes each guessing rank $1, \ldots, q^m$ exactly once, so
\[
\Exp[G^{\rho}] = \frac{1}{q^m}\sum_{j=1}^{q^m} j^{\rho}.
\]
A \emph{coset code} of rate $R$ reduces the number of candidates consistent with the
observed side information from $q^m$ to $q^{k_m}$, where the code dimension $k_m$
satisfies $k_m/m \to R$ as $m \to \infty$. The constrained guesswork moment is
\[
M_q(k_m) = q^{-k_m}\sum_{j=1}^{q^{k_m}} j^{\rho}.
\]

\subsection{Contribution}
We prove that, for every alphabet size $q \ge 2$ and every $\rho > 0$: (i) the
unconstrained guessing exponent (base $q$, per symbol) is exactly $\rho$; (ii) the
constrained exponent under a rate-$R$ coset code is exactly $\rho R$; and hence
(iii) the code lowers the exponent by exactly $\rho(1-R)$, independent of the
alphabet size $q$. The central insight is that the redundancy penalty arises
entirely from the density factor $q^{-k_m}$, whose base-$q$ logarithm is exactly
$-k_m$, and is therefore blind to both the alphabet size and the fine structure of
the power sum.

\section{Definitions}
Throughout, $q = b \ge 2$ is the alphabet size, $\rho > 0$ the moment order, and
$\log_b$ the base-$b$ logarithm.

\begin{definition}[Power sum]
For $\rho \in \mathbb{R}$ and $N \in \mathbb{N}$,
$\displaystyle S_{\rho}(N) = \sum_{k=1}^{N} k^{\rho} = \sum_{k=0}^{N-1}(k+1)^{\rho}.$
\end{definition}

\begin{definition}[$q$-ary guesswork moment]
For a uniform source guessing over $q^k$ equiprobable candidates,
$\displaystyle M_q(k) = q^{-k}\,S_{\rho}(q^k) = q^{-k}\sum_{j=1}^{q^k} j^{\rho}.$
For a sequence of code dimensions $k_m$, the constrained coset moment at block
length $m$ is $M_q(k_m)$.
\end{definition}

\begin{definition}[Rényi entropy]
For a distribution $P$ on $q$ letters and order $\alpha \ne 1$, in base $b$,
$\displaystyle H^{(b)}_{\alpha}(P) = \frac{1}{1-\alpha}\log_b \sum_{i=1}^{q} P(i)^{\alpha}.$
\end{definition}

\begin{definition}[Maximal-entropy Arıkan--Merhav exponent]
The uniform-source guessing exponent of order $\rho$, in base $b$, is
$E^{(b)}_{\mathrm{unif}}(q,\rho) = \rho\,\log_b q$, equal (Proposition~\ref{prop:renyi-exp})
to $\rho$ times the Rényi entropy of order $1/(1+\rho)$ of the uniform law.
\end{definition}

\section{The power-sum estimate}

\begin{lemma}[Positivity]\label{lem:pos}
For every $\rho \in \mathbb{R}$ and $N \ge 1$, $S_{\rho}(N) > 0$.
\end{lemma}
\begin{proof}
Each summand $(k+1)^{\rho}$ is positive and the range is nonempty.
\end{proof}

\begin{lemma}[Upper bound]\label{lem:upper}
For $q \ge 2$, $\rho \ge 0$, and $j \in \mathbb{N}$,
$\displaystyle S_{\rho}(q^j) \le q^{\,j(\rho+1)}.$
\end{lemma}
\begin{proof}
Each of the $q^j$ terms $k^{\rho}$ with $1 \le k \le q^j$ satisfies
$k^{\rho} \le (q^j)^{\rho}$ since $x \mapsto x^{\rho}$ is nondecreasing for
$\rho \ge 0$. Summing gives $S_{\rho}(q^j) \le q^j (q^j)^{\rho} = q^{\,j(\rho+1)}$.
\end{proof}

\begin{lemma}[Lower bound]\label{lem:lower}
For $q \ge 2$, $\rho \ge 0$, and $j \ge 1$,
$\displaystyle q^{\,(j-1)(\rho+1)} \le S_{\rho}(q^j).$
\end{lemma}
\begin{proof}
Restrict the sum to the top block $k \in [q^{j-1}, q^j)$. Each such term satisfies
$k^{\rho} \ge (q^{j-1})^{\rho}$, and the block contains
$q^j - q^{j-1} = q^{j-1}(q-1)$ terms. Since $q \ge 2$, the block count is at least
$q^{j-1}$, so
\[
S_{\rho}(q^j) \ge (q^{j-1})^{\rho}\,(q^j - q^{j-1})
\ge (q^{j-1})^{\rho}\, q^{j-1} = q^{\,(j-1)(\rho+1)}. \qedhere
\]
\end{proof}

\begin{lemma}[Logarithmic sandwich]\label{lem:sandwich}
For $q \ge 2$, $\rho \ge 0$, and $j \ge 1$,
\[
(j-1)(\rho+1) \le \log_q S_{\rho}(q^j) \le j(\rho+1).
\]
\end{lemma}
\begin{proof}
Take base-$q$ logarithms of Lemmas~\ref{lem:upper} and \ref{lem:lower}, using
$\log_q(q^x)=x$ and monotonicity of $\log_q$ (valid since $q>1$ and
$S_{\rho}(q^j)>0$ by Lemma~\ref{lem:pos}).
\end{proof}

\section{The maximal-entropy exponent via Rényi entropy}

\begin{proposition}[Rényi entropy of the uniform law]\label{prop:renyi-unif}
For every order $\alpha \ne 1$ and every $q \ge 1$, the Rényi entropy of the uniform
distribution $P(i)=1/q$ on $q$ letters is $\log_b q$, independent of $\alpha$.
\end{proposition}
\begin{proof}
With $P(i)=q^{-1}$, $\sum_{i=1}^q P(i)^{\alpha} = q\cdot q^{-\alpha}=q^{1-\alpha}$, so
$H^{(b)}_{\alpha} = \tfrac{1}{1-\alpha}\log_b q^{1-\alpha}
= \tfrac{1}{1-\alpha}(1-\alpha)\log_b q = \log_b q$, using $\alpha\ne 1$.
\end{proof}

\begin{proposition}[Exponent as a Rényi entropy]\label{prop:renyi-exp}
For $\rho>0$ and $q\ge 1$,
$E^{(b)}_{\mathrm{unif}}(q,\rho) = \rho\, H^{(b)}_{1/(1+\rho)}\!\big(\tfrac1q,\ldots,\tfrac1q\big).$
\end{proposition}
\begin{proof}
The order $\alpha=1/(1+\rho)\ne 1$ since $\rho>0$; Proposition~\ref{prop:renyi-unif}
gives $\log_b q$, and multiplying by $\rho$ yields $\rho\log_b q$.
\end{proof}

\begin{proposition}[Self-base normalization]\label{prop:selfbase}
For $q \ge 2$ and any $\rho$, $E^{(q)}_{\mathrm{unif}}(q,\rho) = \rho.$
\end{proposition}
\begin{proof}
$E^{(q)}_{\mathrm{unif}}(q,\rho) = \rho\log_q q = \rho\cdot 1 = \rho$, since
$\log_q q = 1$ for $q>1$.
\end{proof}

\section{The exact coset exponent}

\begin{theorem}[Exact constrained $q$-ary coset exponent]\label{thm:main}
Let $q\ge 2$, $\rho>0$, and let $(k_m)_m$ satisfy $k_m\to\infty$ and $k_m/m\to R$.
Then
\[
\frac{1}{m}\,\log_q M_q(k_m) \;\longrightarrow\; \rho R \qquad (m\to\infty).
\]
\end{theorem}
\begin{proof}
By multiplicativity of the logarithm,
$\log_q M_q(k_m) = -k_m + \log_q S_{\rho}(q^{k_m})$. Applying
Lemma~\ref{lem:sandwich} with $j=k_m\ge 1$,
\[
(k_m-1)(\rho+1) \le \log_q S_{\rho}(q^{k_m}) \le k_m(\rho+1),
\]
so, adding $-k_m$,
\[
k_m\rho - (\rho+1) \le \log_q M_q(k_m) \le k_m\rho.
\]
Dividing by $m$,
\[
\frac{k_m}{m}\rho - \frac{\rho+1}{m}
\le \frac{1}{m}\log_q M_q(k_m)
\le \frac{k_m}{m}\rho.
\]
As $m\to\infty$ both bounds tend to $\rho R$ (using $k_m/m\to R$ and
$(\rho+1)/m\to 0$); the squeeze theorem gives the claim.
\end{proof}

\begin{corollary}[Unconstrained rate]\label{cor:unif}
Taking $k_m=m$ (so $R=1$), $\displaystyle \frac{1}{m}\log_q M_q(m)\to\rho.$
\end{corollary}
\begin{proof}
Apply Theorem~\ref{thm:main} with $k_m=m$, giving the limit $\rho\cdot 1=\rho$.
\end{proof}

\begin{theorem}[Exact redundancy shift]\label{thm:shift}
Under the hypotheses of Theorem~\ref{thm:main} and using
Proposition~\ref{prop:selfbase},
\[
\lim_{m\to\infty}\frac{1}{m}\log_q M_q(k_m)
= E^{(q)}_{\mathrm{unif}}(q,\rho) - \rho(1-R).
\]
Consequently the unconstrained exponent $\rho$ and the constrained exponent $\rho R$
differ by exactly $\rho-\rho R = \rho(1-R)$, independent of the alphabet size $q$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:main} the constrained limit is $\rho R$. By
Proposition~\ref{prop:selfbase}, $E^{(q)}_{\mathrm{unif}}(q,\rho)=\rho$, so
$E^{(q)}_{\mathrm{unif}}(q,\rho)-\rho(1-R) = \rho-\rho(1-R) = \rho R$. The identity
$\rho-\rho R=\rho(1-R)$ is algebraic.
\end{proof}

\section{Discussion}

\paragraph{The shift is a pure density effect.}
The logarithm of the moment splits into a density term $-k_m$ and a power-sum term
$\log_q S_{\rho}(q^{k_m})\approx k_m(\rho+1)$; after normalization these contribute
$-R$ and $R(\rho+1)$, summing to $R\rho$. Every trace of the code appears through
$-k_m$, whose base-$q$ logarithm is exactly $-k_m$ regardless of $\rho$ or $q$. This
is why the shift $\rho(1-R)$ is universal across alphabets.

\paragraph{The block-count factor.}
The only structural difference from the binary case is that the lower-bound block
$[q^{j-1},q^j)$ has $q^{j-1}(q-1)$ terms; since $q-1\ge 1$ this only strengthens the
bound and contributes at most an additive $\log_q(q-1)$, which vanishes after
dividing by $m$.

\paragraph{Source term versus code term.}
Propositions~\ref{prop:renyi-unif}--\ref{prop:selfbase} and Theorem~\ref{thm:shift}
exhibit the exponent as a decoupled sum of a source term ($\rho$, from the
maximal-entropy Rényi entropy) and a code term ($-\rho(1-R)$).

\section{Applications}
\begin{itemize}
\item \textbf{Security margins.} For a maximal-entropy secret protected by a rate-$R$
coset code, the guessing exponent of every moment order $\rho$ is $\rho R$.
\item \textbf{Alphabet-agnostic design.} Since the shift $\rho(1-R)$ is independent
of $q$, rules calibrated for bits transfer verbatim to bytes, DNA, or any $q$-ary
channel once information is measured in base $q$.
\item \textbf{Rate--exponent tradeoff.} The linear law $E(\rho,R)=\rho R$ makes the
tradeoff between coding rate and guessing hardness fully explicit.
\end{itemize}

\section{Future work}
\begin{enumerate}
\item \textbf{Non-uniform $q$-ary sources.} Replace the uniform source by a
per-symbol law $P$; ordering noise vectors by decreasing probability and grouping by
type should yield $\rho\,H_{1/(1+\rho)}(P)-\rho(1-R)$, with the code term unchanged.
\item \textbf{Matching converse.} Upgrade the two-sided estimate to a genuine
two-sided exponent, closing the constant gap $q^{\rho+1}$ via an Euler--Maclaurin
expansion of the power sum.
\item \textbf{Random linear codes.} Let $k_m$ and the coset arise from a random
$[n,Rn]$ generator matrix; prove the density factor $q^{-(1-R)n}$ in expectation by a
first-moment argument, then upgrade to high probability.
\item \textbf{Sharper asymptotics.} A second-order analysis of $\sum k^{\rho}$ would
yield the exact constant and the finite-block correction.
\end{enumerate}

\section{Conclusion}
For every alphabet size $q\ge 2$ and moment order $\rho>0$, the maximal-entropy
$q$-ary source has unconstrained guessing exponent $\rho$ and constrained (rate-$R$
coset) exponent $\rho R$; a code therefore lowers the exponent by exactly the
redundancy $\rho(1-R)$, uniformly in $q$. The argument isolates the shift as a pure
density effect carried by the factor $q^{-k_m}$ and identifies the leading $\rho$ as
the maximal-entropy Arıkan--Merhav exponent through an order-independent
Rényi-entropy computation.

