from __future__ import annotations
import math

def power_sum(rho: float, N: int) -> float:
    return sum(k ** rho for k in range(1, N + 1))

def coset_moment(q: int, rho: float, k: int) -> float:
    return (q ** (-k)) * power_sum(rho, q ** k)

def logb(base: float, x: float) -> float:
    return math.log(x) / math.log(base)

def per_symbol_rate(q: int, rho: float, k_m: int, m: int) -> float:
    return (1.0 / m) * logb(q, coset_moment(q, rho, k_m))

if __name__ == '__main__':
    for q in (2, 3, 4):
        for rho, R in ((1.0, 0.5), (2.0, 0.75)):
            print(f'q={q} rho={rho} target rho*R={rho*R:.3f}')
            for m in (4, 8, 12, 16, 20):
                k_m = round(R * m)
                if k_m < 1 or q ** k_m > 2_000_000:
                    continue
                print(f'  m={m:2d} k_m={k_m:2d} rate={per_symbol_rate(q,rho,k_m,m):.5f}')

from __future__ import annotations
import math

def power_sum(rho: float, N: int) -> float:
    return sum(k ** rho for k in range(1, N + 1))

def rate(q: int, rho: float, k: int, m: int) -> float:
    M = (q ** (-k)) * power_sum(rho, q ** k)
    return (1.0 / m) * (math.log(M) / math.log(q))

def max_block(q: int, cap: int = 2_000_000) -> int:
    k = 1
    while q ** (k + 1) <= cap:
        k += 1
    return k

if __name__ == '__main__':
    for q in (2, 3, 4):
        m = max_block(q)
        for rho, R in ((2.0, 0.6), (3.0, 0.4)):
            e_full = rate(q, rho, m, m)
            e_cons = rate(q, rho, max(1, round(R * m)), m)
            print(f'q={q} rho={rho} R={R}: shift~{e_full-e_cons:.4f} '
                  f'predicted {rho*(1-R):.4f}')

from __future__ import annotations
import math

def power_sum(rho: float, N: int) -> float:
    return sum(k ** rho for k in range(1, N + 1))

def sandwich(q: int, rho: float, j: int) -> tuple[float, float, float]:
    return q ** ((j-1)*(rho+1)), power_sum(rho, q ** j), q ** (j*(rho+1))

def renyi_uniform(b: float, alpha: float, q: int) -> float:
    total = sum((1.0 / q) ** alpha for _ in range(q))
    return (1.0 / (1.0 - alpha)) * (math.log(total) / math.log(b))

if __name__ == '__main__':
    for q in (2, 3):
        for rho in (1.0, 2.5):
            for j in (1, 2, 3, 4):
                lo, s, hi = sandwich(q, rho, j)
                print(f'q={q} rho={rho} j={j}: {lo:.2e} <= {s:.2e} <= {hi:.2e} '
                      f"{'OK' if lo <= s <= hi else 'FAIL'}")
    for q in (2, 3, 8):
        vals = [renyi_uniform(2.0, a, q) for a in (0.25, 0.5, 2.0, 5.0)]
        print(f'q={q} log2 q={math.log2(q):.4f} H_alpha={[round(v,4) for v in vals]}')

