function COSET_MOMENT(q, rho, k):
    N <- q^k
    S <- 0
    for j from 1 to N:
        S <- S + j^rho
    return q^(-k) * S

function RENYI_UNIFORM(b, alpha, q):
    assert alpha != 1
    S <- 0
    for i from 1 to q:
        S <- S + (1/q)^alpha
    return (1/(1-alpha)) * log_b(S)

