from __future__ import annotations
import math

def renyi_entropy_uniform(b: float, alpha: float, q: int) -> float:
    """Renyi entropy of order alpha (!=1) of the uniform law on q letters."""
    if alpha == 1.0:
        raise ValueError('alpha must differ from 1')
    total: float = sum((1.0 / q) ** alpha for _ in range(q))
    return (1.0 / (1.0 - alpha)) * (math.log(total) / math.log(b))

